// Auto-generated bilingual ingredient dataset for the Ingredient Check screen.
// Badge tiers: 'safe' | 'cautious' | 'danger' | 'emergency'
export type Badge = 'safe' | 'toxic' | 'emergency';

export interface Bilingual {
  en: string;
  vi: string;
}

export interface BilingualList {
  en: string[];
  vi: string[];
}

// Note: badge only controls the color tier (toxic=yellow / emergency=red / safe=green).
// riskLabel is stored per item and always matches its badge 1:1 here, but kept
// separate in case label text ever needs to diverge from the color again.
export interface IngredientDetails {
  whyTitle: Bilingual;
  why: BilingualList;
  symptomsTitle: Bilingual;
  symptoms: BilingualList;
}

export interface IngredientBenefits {
  benefitsTitle: Bilingual;
  benefits: BilingualList;
  feedingTitle: Bilingual;
  feeding: BilingualList;
}

export interface IngredientItem {
  id: string;
  icon: string;
  badge: Badge;
  title: Bilingual;
  riskLabel: Bilingual;
  shortContent: Bilingual;
  // Present for 'cautious' | 'danger' | 'emergency' items
  details?: IngredientDetails;
  // Present for 'safe' items
  benefits?: IngredientBenefits;
}

